type SegmentEmbed struct { Segment IsSegment }

func (s *SegmentEmbed) parts() ([]string, string, error) {
 switch v := s.Segment.(type) {
 case SegmentKey:
  if v == "" { return nil, "", fmt.Errorf("segment key must not be empty") }
  return []string{string(v)}, "OR_SEGMENT_OPERATOR", nil
 case Segments:
  if len(v.Keys) == 0 { return nil, "", fmt.Errorf("segment keys must not be empty") }
  for _, key := range v.Keys { if key == "" { return nil, "", fmt.Errorf("segment key must not be empty") } }
  if v.SegmentOperator != "AND_SEGMENT_OPERATOR" && v.SegmentOperator != "OR_SEGMENT_OPERATOR" { return nil, "", fmt.Errorf("invalid segment operator %q", v.SegmentOperator) }
  if len(v.Keys) == 1 { return v.Keys, "OR_SEGMENT_OPERATOR", nil }
  return v.Keys, v.SegmentOperator, nil
 default:
  return nil, "", fmt.Errorf("invalid segment format %T", s.Segment)
 }
}

